// Licences (desktop): Praxis Sound's own licence and the third-party notices it ships
// (THIRD-PARTY-NOTICES.txt, generated by docs/release/notices.py; the installer also puts the
// file next to the app). The notices are loaded only when the dialog opens.

import { h } from './dom';
import './packs.css';

/** Window event that opens the dialog (the sounds list's "Licences" button sends it). */
export const OPEN_LICENCES = 'praxis:licences';

export const OWN_LICENCE =
  'Praxis Sound is free software, licensed under the MIT license or the Apache License 2.0, at your option (LICENSE-MIT, LICENSE-APACHE next to the app). It includes the third-party components below under their own licences. The felt piano pack is CC0 (public domain) and is downloaded only when you install it.';

/** Adds the Licences dialog under `root`. */
export function mountLicences(root: HTMLElement): () => void {
  const text = h('pre', { class: 'licences-text', 'data-testid': 'licences-text' }, 'Loading…');
  const dialog = h(
    'dialog',
    { class: 'packs licences', 'aria-labelledby': 'licences-title', 'data-testid': 'licences-dialog' },
    h('div', { class: 'packs-head' }, h('h2', { id: 'licences-title' }, 'Licences'), h('button', { class: 'ghost', onclick: () => dialog.close() }, 'Close')),
    h('p', { class: 'packs-intro' }, OWN_LICENCE),
    text,
  );
  root.append(dialog);
  let loaded = false;
  const open = () => {
    if (!dialog.open) dialog.showModal();
    if (loaded) return;
    loaded = true;
    import('../../../THIRD-PARTY-NOTICES.txt?raw')
      .then((m: { default: string }) => (text.textContent = m.default))
      .catch(() => {
        loaded = false;
        text.textContent = 'The notices could not be loaded; THIRD-PARTY-NOTICES.txt is in the app folder.';
      });
  };
  window.addEventListener(OPEN_LICENCES, open);
  return () => {
    window.removeEventListener(OPEN_LICENCES, open);
    dialog.remove();
  };
}
